 80	<main>
 81	  <h1>Todos</h1>
 82	  <form id="todo-form">
 83	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
 84	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
 85	    <select data-testid="todo-priority" aria-label="Priority">
 86	      <option value="low">Low</option>
 87	      <option value="med" selected>Med</option>
 88	      <option value="high">High</option>
 89	    </select>
 90	    <button type="submit" class="add" data-testid="todo-add">Add</button>
 91	  </form>
 92	  <div class="filters" role="group" aria-label="Filter todos">
 93	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
 94	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
 95	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
 96	  </div>
 97	  <ul data-testid="todo-list"></ul>
 98	  <p class="empty" hidden>No todos yet.</p>
 99	</main>
100	<script>
101	(function () {
102	  var STORAGE_KEY = 'todos';
103	  var form = document.getElementById('todo-form');
104	  var input = document.querySelector('[data-testid="todo-input"]');
105	  var dueInput = document.querySelector('[data-testid="todo-due"]');
106	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
107	  var list = document.querySelector('[data-testid="todo-list"]');
108	  var empty = document.querySelector('.empty');
109	  var filterButtons = document.querySelectorAll('[data-filter]');
110	
111	  var PRIORITIES = ['low', 'med', 'high'];
112	  var DEFAULT_PRIORITY = 'med';
113	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
114	
115	  function normalizePriority(p) {
116	    return PRIORITIES.indexOf(p) !== -1 ? p : DEFAULT_PRIORITY;
117	  }
118	
119	  function load() {
120	    try {
121	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
122	      if (!Array.isArray(data)) return [];
123	      // Todos saved before priorities existed default to "med".
124	      data.forEach(function (t) { t.priority = normalizePriority(t.priority); });
125	      return data;
126	    } catch (e) {
127	      return [];
128	    }
129	  }
130	
131	  function save() {
132	    try {
133	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
134	    } catch (e) {
135	      // Storage may be unavailable (e.g. blocked); the app still works in memory.
136	    }
137	  }
138	
139	  function makeId() {
140	    if (window.crypto && typeof crypto.randomUUID === 'function') {
141	      return crypto.randomUUID();
142	    }
143	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
144	  }
145	
146	  // Date rule (project decision): a due date is a plain "YYYY-MM-DD" string
147	  // meaning a LOCAL calendar date. Never pass it through Date parsing or UTC
148	  // (new Date("YYYY-MM-DD") is UTC midnight). Compare as strings, date-only.
149	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
150	
151	  function pad(n) { return (n < 10 ? '0' : '') + n; }
152	
153	  function todayLocal() {
154	    var d = new Date();
155	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
156	  }
157	
158	  // Overdue: due date strictly before today's local date. Due today is never overdue.
159	  // Zero-padded YYYY-MM-DD strings sort the same as the dates they name.
160	  function isOverdue(todo, today) {
161	    return !!todo.due && todo.due < today;
162	  }
163	
164	  function formatDue(due) {
165	    var parts = due.split('-');
166	    var local = new Date(+parts[0], +parts[1] - 1, +parts[2]);
167	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
168	  }
169	
170	  var todos = load();
171	  var filter = 'all';
172	  var renderedDay = null;
173	
174	  // Ordering rule (project decision): active todos first, completed todos below.
175	  // Within each group, sort by priority (high, med, low); within the same
176	  // priority, keep insertion order (oldest first). `todos` is stored in
177	  // insertion order, and the index tiebreak keeps the sort stable.
178	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
179	
180	  function byPriority(group) {
181	    return group
182	      .map(function (t, i) { return { todo: t, index: i }; })
183	      .sort(function (a, b) {
184	        return (PRIORITY_RANK[a.todo.priority] - PRIORITY_RANK[b.todo.priority]) || (a.index - b.index);
185	      })
186	      .map(function (entry) { return entry.todo; });
187	  }
188	
189	  function visibleTodos() {
190	    var active = byPriority(todos.filter(function (t) { return !t.completed; }));
191	    var completed = byPriority(todos.filter(function (t) { return t.completed; }));
192	    if (filter === 'active') return active;
193	    if (filter === 'completed') return completed;
194	    return active.concat(completed);
195	  }
196	
197	  function render() {
198	    list.textContent = '';
199	    var visible = visibleTodos();
200	    var today = todayLocal();
201	    renderedDay = today;
202	    visible.forEach(function (todo) {
203	      var li = document.createElement('li');
204	      li.setAttribute('data-testid', 'todo-item');
205	      li.setAttribute('data-id', todo.id);
206	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
207	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
208	      li.setAttribute('data-priority', todo.priority);
209	
210	      var toggle = document.createElement('input');
211	      toggle.type = 'checkbox';
212	      toggle.checked = !!todo.completed;
213	      toggle.setAttribute('data-testid', 'todo-toggle');
214	      toggle.setAttribute('aria-label', 'Mark complete');
215	      toggle.addEventListener('change', function () { setCompleted(todo.id, toggle.checked); });
216	
217	      var text = document.createElement('span');
218	      text.className = 'text';
219	      text.setAttribute('data-testid', 'todo-text');
220	      text.textContent = todo.text;
221	
222	      var del = document.createElement('button');
223	      del.type = 'button';
224	      del.className = 'delete';
225	      del.setAttribute('data-testid', 'todo-delete');
226	      del.setAttribute('aria-label', 'Delete todo');
227	      del.textContent = 'Delete';
228	      del.addEventListener('click', function () { remove(todo.id); });
229	
230	      var priority = document.createElement('span');
231	      priority.className = 'priority';
232	      priority.setAttribute('data-testid', 'todo-priority-label');
233	      priority.textContent = PRIORITY_LABELS[todo.priority];
234	
235	      li.appendChild(toggle);
236	      li.appendChild(text);
237	      li.appendChild(priority);
238	      if (todo.due) {
239	        var due = document.createElement('time');
240	        due.className = 'due';
241	        due.setAttribute('data-testid', 'todo-due-date');
242	        due.setAttribute('datetime', todo.due);
243	        due.textContent = 'Due ' + formatDue(todo.due);
244	        li.appendChild(due);
245	      }
246	      li.appendChild(del);
247	      list.appendChild(li);
248	    });
249	    empty.textContent = todos.length === 0 ? 'No todos yet.'
250	      : filter === 'active' ? 'No active todos.'
251	      : 'No completed todos.';
252	    empty.hidden = visible.length > 0;
253	    filterButtons.forEach(function (btn) {
254	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
255	    });
256	  }
257	
258	  function add(text, due, priority) {
259	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: normalizePriority(priority) });
260	    save();
261	    render();
262	  }
263	
264	  function remove(id) {
265	    todos = todos.filter(function (t) { return t.id !== id; });
266	    save();
267	    render();
268	  }
269	
270	  function setCompleted(id, completed) {
271	    todos.forEach(function (t) { if (t.id === id) t.completed = completed; });
272	    save();
273	    render();
274	  }
275	
276	  filterButtons.forEach(function (btn) {
277	    btn.addEventListener('click', function () {
278	      filter = btn.getAttribute('data-filter');
279	      render();
280	    });
281	  });
282	
283	  form.addEventListener('submit', function (e) {
284	    e.preventDefault();
285	    var text = input.value.trim();
286	    if (!text) return;
287	    var due = DATE_RE.test(dueInput.value) ? dueInput.value : null;
288	    add(text, due, priorityInput.value);
289	    input.value = '';
290	    dueInput.value = '';
291	    priorityInput.value = DEFAULT_PRIORITY;
292	    input.focus();
293	  });
294	
295	  render();
296	
297	  // Overdue status changes at local midnight; re-render when the day rolls over.
298	  setInterval(function () {
299	    if (todayLocal() !== renderedDay) render();
300	  }, 30000);
301	})();
302	</script>
303	</body>
304	</html>

