204	      li.setAttribute('data-testid', 'todo-item');
205	      li.setAttribute('data-id', todo.id);
206	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
207	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
208	      li.setAttribute('data-priority', todo.priority);
209	
210	      var toggle = document.createElement('input');
211	      toggle.type = 'checkbox';
212	      toggle.checked = !!todo.completed;
213	      toggle.setAttribute('data-testid', 'todo-toggle');
214	      toggle.setAttribute('aria-label', 'Mark complete');
215	      toggle.addEventListener('change', function () { setCompleted(todo.id, toggle.checked); });
216	
217	      var text = document.createElement('span');
218	      text.className = 'text';
219	      text.setAttribute('data-testid', 'todo-text');
220	      text.textContent = todo.text;
221	
222	      var del = document.createElement('button');
223	      del.type = 'button';
224	      del.className = 'delete';
225	      del.setAttribute('data-testid', 'todo-delete');
226	      del.setAttribute('aria-label', 'Delete todo');
227	      del.textContent = 'Delete';
228	      del.addEventListener('click', function () { remove(todo.id); });
229	
230	      var priority = document.createElement('span');
231	      priority.className = 'priority';
232	      priority.setAttribute('data-testid', 'todo-priority-label');
233	      priority.textContent = PRIORITY_LABELS[todo.priority];
234	
235	      li.appendChild(toggle);
236	      li.appendChild(text);
237	      li.appendChild(priority);
238	      if (todo.due) {
239	        var due = document.createElement('time');
240	        due.className = 'due';
241	        due.setAttribute('data-testid', 'todo-due-date');
242	        due.setAttribute('datetime', todo.due);
243	        due.textContent = 'Due ' + formatDue(todo.due);
244	        li.appendChild(due);
245	      }
246	      li.appendChild(del);
247	      list.appendChild(li);
248	    });
249	    empty.textContent = todos.length === 0 ? 'No todos yet.'
250	      : filter === 'active' ? 'No active todos.'
251	      : 'No completed todos.';
252	    empty.hidden = visible.length > 0;
253	    filterButtons.forEach(function (btn) {
254	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
255	    });
256	  }
257	
258	  function add(text, due, priority) {
259	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: normalizePriority(priority) });
260	    save();
261	    render();
262	  }
263	
264	  function remove(id) {
265	    todos = todos.filter(function (t) { return t.id !== id; });
266	    save();
267	    render();
268	  }
269	
270	  function setCompleted(id, completed) {
271	    todos.forEach(function (t) { if (t.id === id) t.completed = completed; });
272	    save();
273	    render();
274	  }
275	
276	  filterButtons.forEach(function (btn) {
277	    btn.addEventListener('click', function () {
278	      filter = btn.getAttribute('data-filter');
279	      render();
280	    });
281	  });
282	
283	  form.addEventListener('submit', function (e) {
284	    e.preventDefault();
285	    var text = input.value.trim();
286	    if (!text) return;
287	    var due = DATE_RE.test(dueInput.value) ? dueInput.value : null;
288	    add(text, due, priorityInput.value);
289	    input.value = '';
290	    dueInput.value = '';
291	    priorityInput.value = DEFAULT_PRIORITY;
292	    input.focus();
293	  });
294	
295	  render();
296	
297	  // Overdue status changes at local midnight; re-render when the day rolls over.
298	  setInterval(function () {
299	    if (todayLocal() !== renderedDay) render();
300	  }, 30000);
301	})();
302	</script>
303	</body>
304	</html>

